.darma-loader-darma-b12-vault-dial { --accent: var(--loader-color, #334155); --accent-2: var(--loader-secondary-color, #eab308); width: var(--loader-size, 92px); height: var(--loader-size, 92px); position: relative; display: grid; place-items: center; border-radius: 50%; background: radial-gradient(circle, #e2e8f0 62%, #cbd5e1); box-shadow: inset 0 0 0 2px #94a3b8; }
.darma-loader-darma-b12-vault-dial::before { content: ''; position: absolute; inset: 5%; border-radius: 50%; background: repeating-conic-gradient(var(--accent-2) 0 1.4deg, transparent 1.4deg 12deg); }
.darma-loader-darma-b12-vault-dial .darma-loader-darma-b12-vault-dial__dial { position: relative; width: 70%; height: 70%; border-radius: 50%; background: conic-gradient(from 0deg, var(--accent), var(--accent-2), var(--accent)); box-shadow: 0 3px 8px rgba(15, 23, 42, .3); animation: darma-loader-darma-b12-vault-dial-vault calc(var(--loader-speed, 1s) * 3) cubic-bezier(.62, 0, .3, 1) infinite; }
.darma-loader-darma-b12-vault-dial .darma-loader-darma-b12-vault-dial__dial::after { content: ''; position: absolute; top: 7%; left: calc(50% - 4%); width: 8%; height: 26%; border-radius: 999px; background: #f8fafc; }
@keyframes darma-loader-darma-b12-vault-dial-vault { 0% { transform: rotate(0deg); } 22% { transform: rotate(148deg); } 40% { transform: rotate(104deg); } 62% { transform: rotate(268deg); } 80% { transform: rotate(220deg); } 100% { transform: rotate(360deg); } }

